   + '$("sl").textContent=st.live?"Showing the time right now":"Showing "+ft(hp)+" in Dubai";$("sc").value=st.min;$("dp").value=st.day;$("nb").style.display=st.live?"none":"";'
   + 'var rs=$("rows");rs.innerHTML="";'
