sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);sun.shadow.bias=-0.0004;sun.shadow.normalBias=0.6;
const fill=new THREE.DirectionalLight(0x3E8A7E,0.35);fill.position.set(-1,0.4,-0.8);scene.add(fill);
