  const rt=new THREE.WebGLRenderTarget(W*pr,H*pr,{type:THREE.HalfFloatType,samples:MOBILE?0:4});
  bloomC=new EffectComposer(ren);bloomC.renderToScreen=false;bloomC.addPass(new RenderPass(scene,cam));
